content.text:
{
  "name": "同步 Unix 套接字客户端",
  "name_en": "Synchronous Unix Socket Client",
  "manufacturer": "",
  "description": "用于实验软件系统中的非物理通信组件，通过 Unix 域套接字与本机服务进程建立同步连接、发送消息并接收响应，适合本地控制服务、进程间通信和命令转发场景。",
  "description_en": "A non-physical communication component used in laboratory software systems. It establishes synchronous connections to a local service process over a Unix domain socket, sends messages, and receives responses for local control services, inter-process communication, and command forwarding.",
  "actions": [
    {
      "action_name": "auto-is_connected",
      "description": "检查是否已连接到 Unix 套接字服务器。",
      "description_en": "Check whether the client is connected to the Unix socket server."
    },
    {
      "action_name": "auto-connect",
      "description": "连接到 Unix 套接字服务器。",
      "description_en": "Connect to the Unix socket server."
    },
    {
      "action_name": "auto-send_message",
      "description": "向服务器发送一条消息。",
      "description_en": "Send a message to the server."
    },
    {
      "action_name": "auto-recv_message",
      "description": "从服务器接收一条完整消息。",
      "description_en": "Receive a complete message from the server."
    },
    {
      "action_name": "auto-send_and_receive",
      "description": "以同步且互斥的方式发送消息并接收响应，避免线程间收发交错。",
      "description_en": "Send a message and receive the response atomically with mutual exclusion, preventing interleaved send/receive operations across threads."
    },
    {
      "action_name": "auto-close",
      "description": "关闭与 Unix 套接字服务器的连接。",
      "description_en": "Close the connection to the Unix socket server."
    }
  ],
  "tag_hints": [
    "Unix domain socket",
    "synchronous IPC",
    "local server communication",
    "message transport",
    "thread-safe request-response",
    "lab software integration"
  ]
}

